export const STORAGE_PREFIX: string;
export const SESSION_KEY: string;
export const LINES_KEY: string;
export const APPROACH_PROP: {
  hinge: { x: number; y: number; z: number };
  length: number;
  width: number;
  thickness: number;
  mass: number;
  uprightLeanDeg: number;
  restitution: number;
  friction: number;
  angularDamping: number;
  linearDamping: number;
  lip: { x: number; y: number; z: number; w: number; h: number; d: number; restitution: number; friction: number };
};
export const HINGE_LIMIT: { axis: string; min: number; max: number };
export const STANDING_FLOOR: 'A';
export const LATCH_LEAN_DEGREES: number;
export const YARD_CHANGE_DEGREES: number;
export const ARM_CODES: Readonly<Record<string, 'address' | 'recording'>>;
export function resolveArm(code: string | null | undefined): 'address' | 'recording';
export function isLatch(hit: boolean, lean: number | null): boolean;
export function yardChanged(lean: number | null, upright?: number): boolean;
export type ApproachMemory = {
  charge: number;
  environment: { floor: 'A' };
  propAtAddress: ApproachPose | null;
  setup: AimSetup | null;
};
export type ApproachPose = {
  lean: number;
  x: number;
  y: number;
  z: number;
  qx: number;
  qy: number;
  qz: number;
  qw: number;
};
export type AimSetup = { railIndex: number; yaw: number; elevation: number; charge: number };
export function approachMemory(shot: { charge: number; propAtAddress?: ApproachPose | null; setup?: AimSetup | null } | null | undefined): ApproachMemory | undefined;
export type ShotRecord = {
  build: string;
  armCode: string;
  plan: string;
  timberBefore: ApproachPose | null;
  timberAfter: ApproachPose | null;
  latched: boolean;
  continueOffered: boolean;
  continueUsed: boolean;
  treadContacts: string[];
  firstGround: { x: number; y: number; z: number } | null;
  setup: AimSetup | null;
  terminal: { x: number; y: number; z: number } | null;
  at: string | null;
};
export function shotRecord(input: Partial<ShotRecord> & Record<string, unknown>): ShotRecord;
export type RecoveryDeps = {
  memory: () => ({ charge: number; propAtAddress?: ApproachPose | null; setup?: AimSetup | null } | null | undefined);
  livePose: () => ApproachPose | 'standing';
  interrupt: () => void;
  cancel: () => void;
  applyPose: (pose: ApproachPose | 'standing') => void;
  loadAim: (restore: boolean) => void;
  exactPower: (power: number) => void;
  noteRestore: (state: unknown) => void;
  address: () => void;
  showGhost: () => void;
  loadStation: (id: string) => void;
  stationId: string;
};
export function runApproachRecovery(action: string, deps: RecoveryDeps): { called: string; accepted: boolean; reason?: string };
